using System;using System.Drawing;using System.IO;using System.Threading.Tasks;using System.Windows.Forms;
internal sealed class InkDialog:Form{
 readonly TextBox text=new TextBox(),chat=new TextBox(),secondary=new TextBox(),canvas=new TextBox();readonly Label status=new Label();bool busy;
 internal string Draft(string role){return role=="chat"?chat.Text:role=="secondary"?secondary.Text:role=="canvas"?canvas.Text:text.Text;}
 internal void SetDraft(string role,string value){(role=="chat"?chat:role=="secondary"?secondary:role=="canvas"?canvas:text).Text=value;}
 internal void SaveDraftOnly(){foreach(var b in new[]{text,chat,secondary,canvas})if(b.Text!="original"&&b.Text!="auto"&&!Palette.IsColor(b.Text))throw new IOException("请修正文字色值。");NativeBackground.InkText=text.Text;NativeBackground.InkChat=chat.Text;NativeBackground.InkSecondary=secondary.Text;NativeBackground.InkCanvas=canvas.Text;}
 public bool OperationBusy{get{return busy;}}
 public InkDialog(Action<string> changed){Text="消息与文字";Font=new Font("Microsoft YaHei UI",10);BackColor=Color.White;ClientSize=new Size(840,560);StartPosition=FormStartPosition.CenterParent;
  Heading("共同文字",22,18);Note("以下两项目前共同作用于发送和接收消息。",22,54,790,28);
  Row("界面文字",text,NativeBackground.InkText,100);Row("聊天正文（共用）",chat,NativeBackground.InkChat,154);
  Heading("界面层级与壁纸上的文字",22,226);
  Row("摘要、时间等次级文字",secondary,NativeBackground.InkSecondary,274);Row("壁纸上的昵称与时间",canvas,NativeBackground.InkCanvas,328);
  Note("主文字、次级文字和壁纸上的说明文字分别调色；头像和表情保留原色。\n发送／接收气泡底色在「基础配色」分别设置。",22,390,790,60);
  var apply=new Button{Text="保存并应用",Location=new Point(22,478),Size=new Size(180,36)};Controls.Add(apply);apply.Click+=async delegate{await ApplyWorkspace();};
  var reset=new Button{Text="恢复文字原色",Location=new Point(220,478),Size=new Size(180,36)};Controls.Add(reset);reset.Click+=async delegate{text.Text=chat.Text=secondary.Text=canvas.Text="original";await ApplyWorkspace();};status.SetBounds(22,526,790,28);Controls.Add(status);
 }
 void Heading(string value,int x,int y){Controls.Add(new Label{Text=value,Font=new Font(Font.FontFamily,13,FontStyle.Bold),Location=new Point(x,y),Size=new Size(780,28)});}
 void Note(string value,int x,int y,int w,int h){Controls.Add(new Label{Text=value,Location=new Point(x,y),Size=new Size(w,h),ForeColor=Color.FromArgb(91,103,117)});}
 void Row(string label,TextBox box,string value,int y){Controls.Add(new Label{Text=label,Location=new Point(22,y+6),Size=new Size(190,28)});box.Text=value;box.SetBounds(214,y,130,32);Controls.Add(box);int x=358;foreach(string preset in box==canvas?new[]{"黑色","白色","智能","原色","自选…"}:new[]{"黑色","白色","原色","自选…"}){string choice=preset;var b=new Button{Text=choice,Location=new Point(x,y),Size=new Size(box==canvas?88:100,32)};Controls.Add(b);b.Click+=delegate{if(choice=="自选…"){using(var d=new StudioColorPicker{FullOpen=true,Color=Palette.IsColor(box.Text)?ColorTranslator.FromHtml(box.Text):Color.White})if(d.ShowDialog(this)==DialogResult.OK)box.Text=String.Format("#{0:X2}{1:X2}{2:X2}",d.Color.R,d.Color.G,d.Color.B);}else box.Text=choice=="黑色"?"#000000":choice=="白色"?"#FFFFFF":choice=="智能"?"auto":"original";};x+=box==canvas?94:112;}}
 public async Task ApplyWorkspace(){if(busy)return;string oldText=NativeBackground.InkText,oldChat=NativeBackground.InkChat,oldSecondary=NativeBackground.InkSecondary,oldCanvas=NativeBackground.InkCanvas;try{if((text.Text!="original"&&!Palette.IsColor(text.Text))||(chat.Text!="original"&&!Palette.IsColor(chat.Text)))throw new IOException("请输入 #RRGGBB，或选择原色。");foreach(var box in new[]{secondary,canvas})if(box.Text!="original"&&!Palette.IsColor(box.Text)&&!(box==canvas&&box.Text=="auto"))throw new IOException("请输入 #RRGGBB，或选择原色。");string source=AutoBackground.SavedImage();if(source==null)throw new IOException("请先在壁纸页面选择并应用图片。");busy=true;Enabled=false;NativeBackground.InkText=text.Text;NativeBackground.InkChat=chat.Text;NativeBackground.InkSecondary=secondary.Text;NativeBackground.InkCanvas=canvas.Text;status.Text="正在应用共同文字设置…";for(int attempt=0;;attempt++){bool retry=false;try{await Task.Run(()=>NativeBackground.Apply(source));break;}catch(IOException e){if(attempt>=4||!e.Message.Contains("另一项背景操作"))throw;retry=true;}if(retry)await Task.Delay(600);}status.Text="文字设置已应用；图标和壁纸设置保持独立。";}catch(Exception e){NativeBackground.InkText=oldText;NativeBackground.InkChat=oldChat;NativeBackground.InkSecondary=oldSecondary;NativeBackground.InkCanvas=oldCanvas;status.Text=e.Message;}finally{busy=false;Enabled=true;}}
}
